import{_ as a,o as r,c as s,a3 as e}from"./chunks/framework.D81Tvp8W.js";const c=JSON.parse('{"title":"CV 技术演进","description":"","frontmatter":{"title":"CV 技术演进","date":"2025-09-02T00:00:00.000Z","categories":["ai","CV"],"tags":["AI","CV"]},"headers":[],"relativePath":"ai/CV/3.技术演进.md","filePath":"ai/CV/3.技术演进.md","lastUpdated":1786872962000}'),n={name:"ai/CV/3.技术演进.md"};function o(d,t,i,l,h,p){return r(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="🧩-cv-技术演进" tabindex="-1">🧩 CV 技术演进 <a class="header-anchor" href="#🧩-cv-技术演进" aria-label="Permalink to &quot;🧩 CV 技术演进&quot;">​</a></h1><p>CV 的技术发展可以概括为：从 <strong>手工特征</strong> 到 <strong>自动学习</strong>，从 <strong>卷积网络</strong> 到 <strong>Transformer</strong> 再到 <strong>生成模型</strong>。</p><hr><h2 id="📈-演进总览" tabindex="-1">📈 演进总览 <a class="header-anchor" href="#📈-演进总览" aria-label="Permalink to &quot;📈 演进总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>代表</th><th>特点</th></tr></thead><tbody><tr><td><strong>传统方法</strong></td><td>HOG、SIFT</td><td>手工设计特征 + 分类器</td></tr><tr><td><strong>CNN 时代</strong></td><td>LeNet、AlexNet、ResNet</td><td>卷积自动提取特征</td></tr><tr><td><strong>检测网络</strong></td><td>YOLO、Faster R-CNN</td><td>端到端目标检测</td></tr><tr><td><strong>Transformer</strong></td><td>ViT、DETR</td><td>注意力机制进入视觉</td></tr><tr><td><strong>生成模型</strong></td><td>GAN、扩散模型</td><td>图像生成、可控创作</td></tr></tbody></table><hr><h2 id="🧱-一、传统方法-2012-之前" tabindex="-1">🧱 一、传统方法（2012 之前） <a class="header-anchor" href="#🧱-一、传统方法-2012-之前" aria-label="Permalink to &quot;🧱 一、传统方法（2012 之前）&quot;">​</a></h2><p>靠人工设计特征描述图像：</p><ul><li><strong>SIFT</strong>：尺度不变特征，用于匹配与拼接</li><li><strong>HOG</strong>：方向梯度直方图，用于行人检测</li><li><strong>Haar</strong>：用于人脸检测（早期 Viola-Jones）</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>图像 → 手工特征（SIFT/HOG/Haar）→ 分类器（SVM）→ 结果</span></span></code></pre></div><p><strong>局限</strong>：特征靠专家设计，泛化差，无法应对复杂场景。</p><hr><h2 id="🌀-二、cnn-时代-2012-2017" tabindex="-1">🌀 二、CNN 时代（2012-2017） <a class="header-anchor" href="#🌀-二、cnn-时代-2012-2017" aria-label="Permalink to &quot;🌀 二、CNN 时代（2012-2017）&quot;">​</a></h2><p><strong>AlexNet</strong>（2012）在 ImageNet 上大幅领先，深度学习全面进入 CV。</p><p><strong>CNN 的核心思想</strong>：卷积核自动学习特征，无需人工设计。</p><table tabindex="0"><thead><tr><th>里程碑</th><th>贡献</th></tr></thead><tbody><tr><td><strong>LeNet</strong>（1998）</td><td>最早的手写数字识别 CNN</td></tr><tr><td><strong>AlexNet</strong>（2012）</td><td>深度 CNN + ReLU + GPU，引爆深度学习</td></tr><tr><td><strong>VGG</strong>（2014）</td><td>小卷积核堆叠，网络加深</td></tr><tr><td><strong>GoogLeNet</strong>（2014）</td><td>Inception 模块</td></tr><tr><td><strong>ResNet</strong>（2015）</td><td>残差连接，解决深层网络退化</td></tr></tbody></table><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ResNet 残差块思想：学习残差 F(x)，输出 F(x) + x</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 让深层网络也能收敛</span></span></code></pre></div><blockquote><p>💡 完整实现见本站 <a href="./../DeepLearning/卷积神经网络/">卷积神经网络</a> 与 <a href="./../DeepLearning/现代卷积神经网络/">现代卷积神经网络</a>。</p></blockquote><hr><h2 id="🎯-三、检测网络-2015" tabindex="-1">🎯 三、检测网络（2015-） <a class="header-anchor" href="#🎯-三、检测网络-2015" aria-label="Permalink to &quot;🎯 三、检测网络（2015-）&quot;">​</a></h2><p>从&quot;分类整图&quot;走向&quot;定位物体&quot;：</p><table tabindex="0"><thead><tr><th>流派</th><th>代表</th><th>特点</th></tr></thead><tbody><tr><td><strong>两阶段</strong></td><td>Faster R-CNN、Mask R-CNN</td><td>先提候选框再分类，精度高</td></tr><tr><td><strong>单阶段</strong></td><td>YOLO、SSD</td><td>一步到位，速度快</td></tr><tr><td><strong>Transformer</strong></td><td>DETR</td><td>端到端，无锚框</td></tr></tbody></table><hr><h2 id="⚡-四、transformer-进入视觉-2020" tabindex="-1">⚡ 四、Transformer 进入视觉（2020-） <a class="header-anchor" href="#⚡-四、transformer-进入视觉-2020" aria-label="Permalink to &quot;⚡ 四、Transformer 进入视觉（2020-）&quot;">​</a></h2><p><strong>ViT（Vision Transformer）</strong>：把图像切成 patch，用 Transformer 处理，不再依赖卷积。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>图像 → 切块（patch）→ 线性映射 → Transformer 编码器 → 分类</span></span></code></pre></div><table tabindex="0"><thead><tr><th>模型</th><th>创新</th></tr></thead><tbody><tr><td><strong>ViT</strong></td><td>纯 Transformer 做图像分类</td></tr><tr><td><strong>DETR</strong></td><td>Transformer 做目标检测</td></tr><tr><td><strong>Swin Transformer</strong></td><td>分层窗口注意力，适配多尺度</td></tr></tbody></table><blockquote><p>💡 Transformer 原理见本站 <a href="./../DeepLearning/注意力机制/">注意力机制</a>。</p></blockquote><hr><h2 id="🎨-五、生成模型-2014" tabindex="-1">🎨 五、生成模型（2014-） <a class="header-anchor" href="#🎨-五、生成模型-2014" aria-label="Permalink to &quot;🎨 五、生成模型（2014-）&quot;">​</a></h2><p>从&quot;理解图像&quot;走向&quot;生成图像&quot;：</p><table tabindex="0"><thead><tr><th>技术</th><th>特点</th></tr></thead><tbody><tr><td><strong>GAN</strong>（2014）</td><td>生成器 vs 判别器对抗，图像逼真</td></tr><tr><td><strong>VAE</strong></td><td>变分自编码器，潜空间可控</td></tr><tr><td><strong>扩散模型</strong>（2020）</td><td>逐步去噪，质量最高</td></tr><tr><td><strong>文生图</strong></td><td>文本引导生成（Stable Diffusion、DALL·E）</td></tr></tbody></table><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 扩散模型思路</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 训练：给图片逐步加噪，学习预测噪声</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 生成：从纯噪声开始，逐步去噪得到图片</span></span></code></pre></div><hr><h2 id="🧠-六、两大主线" tabindex="-1">🧠 六、两大主线 <a class="header-anchor" href="#🧠-六、两大主线" aria-label="Permalink to &quot;🧠 六、两大主线&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理解主线：分类 → 检测 → 分割 → 姿态（越来越精细）</span></span>
<span class="line"><span>生成主线：GAN → 扩散模型 → 可控文生图（越来越强）</span></span></code></pre></div><p>两条主线在 <strong>自监督预训练</strong> 和 <strong>大模型</strong> 上逐渐汇合。</p><hr><h2 id="🎯-小结" tabindex="-1">🎯 小结 <a class="header-anchor" href="#🎯-小结" aria-label="Permalink to &quot;🎯 小结&quot;">​</a></h2><ul><li>传统方法靠手工特征，CNN 让特征自动学习</li><li>检测从两阶段走向单阶段，再到端到端 Transformer</li><li>ViT 让视觉拥抱注意力机制</li><li>扩散模型开启了高质量的图像生成时代</li></ul><blockquote><p>下一步：<a href="./4.学习路线.html">学习路线</a></p></blockquote><hr>`,42)])])}const b=a(n,[["render",o]]);export{c as __pageData,b as default};
